draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'red';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 50, H / 2 + Math.cos(t + i * 1.5) * 50, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  ctx.arc(W / 2, H / 2, 70, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Pomegranate Seeds: Ruby Jewels', W / 2, H - 20);
  ctx.restore();
}
